namespace WorkEnv {
 public sealed class Ipv6PathSnapshot {public bool Complete,PotentialAddress,PotentialRoute;public string Signature;public long StartedTicks,CapturedTicks;}
 // Interface for a future read-only policy provider. The product does not yet
 // implement a WFP provider; only independently verified snapshots may assert it.
 public sealed class Ipv6PolicySnapshot {public bool Complete,ScopeComplete,PriorityResolved,ExceptionsResolved,DynamicRulesKnown,AllApplicableBlocked;public string Signature;}
 [StructLayout(LayoutKind.Sequential,Pack=4)] public struct SocketAddress6 {public ushort family,port;public uint flow;public ulong a,b;public uint scope;}
 [StructLayout(LayoutKind.Sequential)] public struct AddressPrefix6 {public SocketAddress6 address;public byte length;}
 [StructLayout(LayoutKind.Sequential)] public struct RouteRow6 {public ulong luid;public uint index;public AddressPrefix6 destination;public SocketAddress6 next;public byte site;public uint valid,preferred,metric,protocol;public byte loopback,autoconf,publish,immortal;public uint age,origin;}
 [StructLayout(LayoutKind.Sequential)] public struct RouteHead6 {public uint count;public RouteRow6 first;}
 public static class LocalState {
  [DllImport("iphlpapi.dll")] static extern uint GetIpForwardTable2(ushort family,out IntPtr table);
  [DllImport("iphlpapi.dll")] static extern void FreeMibTable(IntPtr table);
  static string IPv6(SocketAddress6 s){if(s.family!=23)throw new InvalidOperationException("route address family mismatch");var bytes=new byte[16];Array.Copy(BitConverter.GetBytes(s.a),0,bytes,0,8);Array.Copy(BitConverter.GetBytes(s.b),0,bytes,8,8);return new IPAddress(bytes,s.scope).ToString();}
  public static string RouteIdentity(RouteRow6 row){if(row.destination.length>128)throw new InvalidOperationException("invalid route prefix");return "route|"+row.luid+"|"+row.index+"|"+IPv6(row.destination.address)+"/"+row.destination.length+"|"+IPv6(row.next)+"|valid="+(row.valid!=0)+"|"+row.metric+"|"+row.protocol+"|"+row.origin+"|"+row.immortal;}
  // This proves only a narrow absence case for the current system routing table.
  // Any uncertainty, route, global/ULA address, or snapshot change remains unknown.
  public static bool Ipv6SnapshotsConsistent(Ipv6PathSnapshot before,Ipv6PathSnapshot after){long now=Stopwatch.GetTimestamp();return before!=null&&after!=null&&before.StartedTicks>0&&before.CapturedTicks>=before.StartedTicks&&after.StartedTicks>=before.CapturedTicks&&after.CapturedTicks>=after.StartedTicks&&after.CapturedTicks<=now&&(before.CapturedTicks-before.StartedTicks)/(double)Stopwatch.Frequency<5&&(after.CapturedTicks-after.StartedTicks)/(double)Stopwatch.Frequency<5&&(after.CapturedTicks-before.StartedTicks)/(double)Stopwatch.Frequency<30&&(now-after.CapturedTicks)/(double)Stopwatch.Frequency<30&&before.Complete&&after.Complete&&!String.IsNullOrEmpty(before.Signature)&&before.Signature==after.Signature&&before.PotentialAddress==after.PotentialAddress&&before.PotentialRoute==after.PotentialRoute;}
  public static Item EvaluateIpv6Path(Ipv6PathSnapshot before,Ipv6PathSnapshot after){bool complete=Ipv6SnapshotsConsistent(before,after);bool absent=complete&&!before.PotentialAddress&&!after.PotentialAddress&&!before.PotentialRoute&&!after.PotentialRoute;var item=new Item("ipv6-path",absent?"pass":"unknown","只读本机接口与 IPv6 路由前后快照",absent?"本轮探测前后快照一致：未发现可用的非本地 IPv6 地址或可通往非本地目的地的路由":"无法以前后快照确认当前系统 IPv6 无通路；可能存在地址、路由、读取失败、状态变化或观察过期","仅覆盖本机 IPv6 地址和路由快照；不证明防火墙阻断、代理或应用隧道的行为，网络变化后失效。","如需核对其他应用路径，请分别验证。");item.identity=absent?"ipv6-path-no-path":"ipv6-path-unverified";item.evidencePhase="local-route-bracket";item.evidenceScope="system-ipv6;active-adapters;all-route-entries;before-after;under-30s";item.failureCode=complete?null:"incomplete-changed-or-expired";item.rawResult=absent?"no-local-system-path":"unknown";return item;}
  public static Item EvaluateIpv6Policy(Ipv6PolicySnapshot first,Ipv6PolicySnapshot second){Func<Ipv6PolicySnapshot,bool> complete=x=>x!=null&&x.Complete&&x.ScopeComplete&&x.PriorityResolved&&x.ExceptionsResolved&&x.DynamicRulesKnown&&x.AllApplicableBlocked&&!String.IsNullOrEmpty(x.Signature);bool blocked=complete(first)&&complete(second)&&first.Signature==second.Signature;var item=new Item("ipv6-path",blocked?"pass":"unknown","只读策略提供方的双快照",blocked?"已提供完整一致的 IPv6 非本地路径阻断证据":"策略证据不完整、存在例外、权限不足或发生变化，无法确认系统阻断","仅适用于提供方实际覆盖的系统 IPv6 范围；本产品尚未实现 WFP 策略提供方。","核对权限、规则覆盖与例外；缺少证据时保持未验证。");item.identity=blocked?"ipv6-path-blocked":"ipv6-path-unverified";item.evidencePhase="policy-snapshot";item.evidenceScope="system-ipv6;nonlocal;two-snapshots";item.failureCode=blocked?null:"policy-unverified";item.rawResult=blocked?"blocked":"unknown";return item;}
  static Ipv6PathSnapshot CaptureIpv6Path(){long started=Stopwatch.GetTimestamp();var sig=new List<string>();bool address=false,route=false;foreach(var n in NetworkInterface.GetAllNetworkInterfaces()){var p=n.GetIPProperties();sig.Add("adapter|"+n.Id+"|"+n.OperationalStatus);foreach(var a in p.UnicastAddresses){if(a.Address.AddressFamily!=AddressFamily.InterNetworkV6)continue;var ip=a.Address;sig.Add("address|"+n.Id+"|"+ip);if(n.OperationalStatus==OperationalStatus.Up&&!IPAddress.IPv6Loopback.Equals(ip)&&!IPAddress.IPv6Any.Equals(ip)&&!ip.IsIPv6LinkLocal&&!ip.IsIPv6Multicast)address=true;}}
   IntPtr table=IntPtr.Zero;try{uint error=GetIpForwardTable2(23,out table);if(error==1168){sig.Add("no-ipv6-routes");}else{if(error!=0||table==IntPtr.Zero)throw new InvalidOperationException("route table unavailable");int count=Marshal.ReadInt32(table);if(count<0||count>65536)throw new InvalidOperationException("invalid route count");int offset=(int)Marshal.OffsetOf(typeof(RouteHead6),"first"),size=Marshal.SizeOf(typeof(RouteRow6));for(int i=0;i<count;i++){var row=(RouteRow6)Marshal.PtrToStructure(IntPtr.Add(table,offset+i*size),typeof(RouteRow6));if(row.destination.length>128)throw new InvalidOperationException("invalid route prefix");var destination=IPAddress.Parse(IPv6(row.destination.address));sig.Add(RouteIdentity(row));bool local=destination.IsIPv6LinkLocal&&row.destination.length>=10||destination.IsIPv6Multicast&&row.destination.length>=8||IPAddress.IPv6Loopback.Equals(destination)&&row.destination.length==128;if(!local)route=true;}}}finally{if(table!=IntPtr.Zero)FreeMibTable(table);}sig.Sort(StringComparer.Ordinal);return new Ipv6PathSnapshot{Complete=true,PotentialAddress=address,PotentialRoute=route,Signature=String.Join(";",sig.ToArray()),StartedTicks=started,CapturedTicks=Stopwatch.GetTimestamp()};}
  public static Ipv6PathSnapshot CaptureIpv6PathSafe(){try{return CaptureIpv6Path();}catch{return new Ipv6PathSnapshot{Complete=false,CapturedTicks=Stopwatch.GetTimestamp()};}}
  public static List<Item> RouteItems(IEnumerable<RouteRow6> rows){var output=new List<Item>();int count=0,defaults=0;foreach(var row in rows){count++;if(row.destination.length>128)throw new InvalidOperationException("invalid IPv6 prefix");string destination=IPv6(row.destination.address),next=IPv6(row.next);if(row.destination.length==0&&destination=="::")defaults++;output.Add(new Item("ipv6-route-entry","pass","Windows IPv6 路由表","目的 "+destination+"/"+row.destination.length+"；下一跳 "+next+"；接口 "+row.index+"；路由跃点数 "+row.metric,"仅表项快照；实际选路还受接口跃点数和策略影响。","需要时结合应用和具体目的地核对。"));}output.Insert(0,new Item("ipv6-route","pass","Windows IPv6 路由表","读取表项 "+count+"；默认路由 "+defaults,"包括本地和远程路由；不证明目标可达或流量泄漏。","查看表项及外部探针结果。"));return output;}
  public static List<Item> ParseRouteTable(IntPtr table){int count=Marshal.ReadInt32(table);if(count<0||count>65536)throw new InvalidOperationException("invalid route count");int offset=(int)Marshal.OffsetOf(typeof(RouteHead6),"first"),size=Marshal.SizeOf(typeof(RouteRow6));var rows=new List<RouteRow6>();for(int i=0;i<count;i++)rows.Add((RouteRow6)Marshal.PtrToStructure(IntPtr.Add(table,offset+i*size),typeof(RouteRow6)));return RouteItems(rows);}
  public static List<Item> ReadIpv6Routes(){IntPtr table=IntPtr.Zero;try{uint error=GetIpForwardTable2(23,out table);if(error==1168)return RouteItems(new RouteRow6[0]);if(error!=0)throw new System.ComponentModel.Win32Exception((int)error);if(table==IntPtr.Zero)throw new InvalidOperationException("route table missing");return ParseRouteTable(table);}catch(Exception e){return new List<Item>{new Item("ipv6-route","unknown","Windows IPv6 路由表",Engine.ErrorCategory(e),"无法读取完整路由表，不代表没有 IPv6 路由。","检查系统权限或平台支持后复查。")};}finally{if(table!=IntPtr.Zero)FreeMibTable(table);}}
  public static Item ProxySummary(int? enabled,bool? autoDetect,bool? pac){if(!enabled.HasValue)return new Item("system-proxy","unknown","当前用户 WinINet 设置","读取失败或代理开关缺失","未覆盖 WinHTTP、环境变量或应用独立代理。","按需核对系统和应用设置。");return new Item("system-proxy","pass","当前用户 WinINet 设置","手动代理："+(enabled.Value!=0?"开启":"关闭")+"；自动检测："+(autoDetect.HasValue?(autoDetect.Value?"开启":"关闭"):"未知")+"；自动配置脚本："+(pac.HasValue?(pac.Value?"已设置":"未设置"):"未知"),"读取状态不判断正确与否；关闭不等于故障；未覆盖 WinHTTP 或应用独立代理。","结合实际应用的代理方式核对。");}
  public static Item ReadProxy(){try{using(var k=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Internet Settings",false)){if(k==null)return ProxySummary(null,null,null);object p=k.GetValue("ProxyEnable"),a=k.GetValue("AutoDetect"),s=k.GetValue("AutoConfigURL");int? enabled=p==null?(int?)null:Convert.ToInt32(p);bool? auto=a==null?(bool?)null:Convert.ToInt32(a)!=0;return ProxySummary(enabled,auto,s!=null&&!String.IsNullOrWhiteSpace(Convert.ToString(s)));}}catch{return ProxySummary(null,null,null);}}
 }
